using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "PurifyCorruptWithMultiplierCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PurifyCorruptWithMultiplierCustomDescription", order = 0)]
public class PurifyCorruptWithMultiplierCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		PurifyCorruptWithMultiplierActions purifyCorruptWithMultiplierActions = battleAction as PurifyCorruptWithMultiplierActions;
		string purifyMultiplierString = GetPurifyMultiplierString(amountModified, purifyCorruptWithMultiplierActions);
		string rawLocalizedDescription = GetRawLocalizedDescription(battleAction);
		string text = "";
		string text2 = "";
		if (purifyCorruptWithMultiplierActions.EnableBasePurifyAmount)
		{
			text = purifyCorruptWithMultiplierActions.PurifyCorruptAction.GetActionDescription(purifyCorruptWithMultiplierActions.BasePurifyAmount);
			if (purifyCorruptWithMultiplierActions.IgnoreForEachOnDescription)
			{
				return text + "\n" + Smart.Format(rawLocalizedDescription, amountModified);
			}
			string text3 = Smart.Format(base.localizationManager.GetLocalizedAdditionalPurify(), GetAmountWithUnlockablesModification(purifyMultiplierString), rawLocalizedDescription);
			return text + "\n" + text3;
		}
		text = purifyCorruptWithMultiplierActions.PurifyCorruptAction.GetActionDescription(GetAmountWithoutEquation(purifyMultiplierString), GetBonusAmountWithoutEquation(purifyMultiplierString));
		if (purifyCorruptWithMultiplierActions.IgnoreForEachOnDescription)
		{
			return text + "\n" + Smart.Format(rawLocalizedDescription, amountModified);
		}
		text = text.RemoveLastIfNotJapaneseNorKoreanNorTraditionalChinese();
		return Smart.Format(base.localizationManager.GetLocalizedForEach(), text, rawLocalizedDescription);
	}

	protected string GetPurifyMultiplierString(string amountModified, PurifyCorruptWithMultiplierActions ba)
	{
		if (!ba.FixedPurifyMultiplier)
		{
			return amountModified;
		}
		return ba.PurifyMultiplier.ToString();
	}
}
